const PROCESSING_FEE: u64 = 5;

/// Every component is insured on the same terms, whatever kind it is.
const COMPONENT_BASE_PREMIUM: u64 = 25;

/// The kind of magical item the MHPCO insures.
pub enum ItemType {
    Sword,
    Amulet,
    Staff,
    Potion,
    Rune,
}

/// How the MHPCO prices an item: main items have their own price-list row,
/// components share uniform component terms.
enum Category {
    MainItem { base_premium: u64 },
    Component,
}

/// An item a customer wishes to insure.
pub struct Item {
    pub item_type: ItemType,
}

/// Computes the premium in whole G for the items a customer wishes to insure.
pub fn quote(items: &[Item]) -> u64 {
    let policy_base_premium: u64 = items.iter().map(base_premium).sum();
    policy_base_premium + PROCESSING_FEE
}

/// The base premium in G the MHPCO charges for one item.
fn base_premium(item: &Item) -> u64 {
    match category(&item.item_type) {
        Category::MainItem { base_premium } => base_premium,
        Category::Component => COMPONENT_BASE_PREMIUM,
    }
}

/// The MHPCO price list: which category an item type falls into, and for a
/// main item the base premium of its own row.
fn category(item_type: &ItemType) -> Category {
    match item_type {
        ItemType::Sword => Category::MainItem { base_premium: 100 },
        ItemType::Amulet => Category::MainItem { base_premium: 60 },
        ItemType::Staff => Category::MainItem { base_premium: 80 },
        ItemType::Potion => Category::MainItem { base_premium: 40 },
        ItemType::Rune => Category::Component,
    }
}
'''
